SELECT rec_id AS id, "ID bản ghi nguồn" AS source_id, "Mã ngân sách" AS code, ("Brand").name AS brand, ("Năm").name AS year, ("Quý ngân sách").name AS quarter, ("Tháng ngân sách").name AS month, "Số tiền TGĐ duyệt" AS amount, "Nội dung chi tiêu" AS content, ("Loại ngân sách").name AS budget_type, ("Loại đề xuất").name AS request_type, "Note" AS note, "Dữ liệu nguồn JSON" AS source_json, "Mốc sao chép" AS copied_at FROM "A03. Ngân sách được duyệt" WHERE rec_id = $1 LIMIT 1
